import { afterEach, describe, expect, it, vi } from "vitest";

import { mapAsync } from "./async-utils.js";

interface Deferred<Value> {
	promise: Promise<Value>;
	resolve(value: Value): void;
	reject(reason: unknown): void;
}

function deferred<Value>(): Deferred<Value> {
	let resolve!: (value: Value) => void;
	let reject!: (reason: unknown) => void;
	const promise = new Promise<Value>((resolvePromise, rejectPromise) => {
		resolve = resolvePromise;
		reject = rejectPromise;
	});
	return { promise, resolve, reject };
}

async function flushMicrotasks(): Promise<void> {
	await Promise.resolve();
	await Promise.resolve();
}

afterEach(() => {
	vi.restoreAllMocks();
});

describe("mapAsync", () => {
	it.each([0, -1, 1.5, Number.NaN, Number.POSITIVE_INFINITY])(
		"rejects invalid concurrency %s",
		async (concurrency) => {
			await expect(mapAsync([], () => undefined, { concurrency })).rejects.toThrow(
				new RangeError("Concurrency must be a positive integer"),
			);
		},
	);

	it("returns an empty result without invoking the mapper", async () => {
		const mapper = vi.fn();

		await expect(mapAsync([], mapper, { concurrency: 3 })).resolves.toEqual([]);
		expect(mapper).not.toHaveBeenCalled();
	});

	it("limits active mappers, starts them in input order, and preserves result order", async () => {
		const gates = Array.from({ length: 5 }, () => deferred<string>());
		const started: number[] = [];
		let active = 0;
		let maximumActive = 0;

		const resultPromise = mapAsync(
			["zero", "one", "two", "three", "four"],
			async (_value, index) => {
				started.push(index);
				active += 1;
				maximumActive = Math.max(maximumActive, active);
				try {
					return await gates[index]!.promise;
				} finally {
					active -= 1;
				}
			},
			{ concurrency: 2 },
		);

		expect(started).toEqual([0, 1]);

		gates[1]!.resolve("result one");
		await flushMicrotasks();
		expect(started).toEqual([0, 1, 2]);

		gates[0]!.resolve("result zero");
		await flushMicrotasks();
		expect(started).toEqual([0, 1, 2, 3]);

		gates[3]!.resolve("result three");
		await flushMicrotasks();
		expect(started).toEqual([0, 1, 2, 3, 4]);

		gates[2]!.resolve("result two");
		gates[4]!.resolve("result four");

		await expect(resultPromise).resolves.toEqual([
			"result zero",
			"result one",
			"result two",
			"result three",
			"result four",
		]);
		expect(maximumActive).toBe(2);
	});

	it("passes each mapper its value, index, and the shared abort signal", async () => {
		const abortController = new AbortController();
		const calls: Array<[string, number, AbortSignal]> = [];

		await mapAsync(
			["a", "b"],
			(value, index, signal) => {
				calls.push([value, index, signal]);
				return value.toUpperCase();
			},
			{ concurrency: 1, abortController },
		);

		expect(calls).toEqual([
			["a", 0, abortController.signal],
			["b", 1, abortController.signal],
		]);
	});

	it("aborts with a mapper error, starts no new work, and drains active mappers", async () => {
		const abortController = new AbortController();
		const firstMapper = deferred<string>();
		const secondMapper = deferred<string>();
		const mapperError = new Error("mapper failed");
		const started: number[] = [];
		let settled = false;

		const resultPromise = mapAsync(
			["first", "second", "never started"],
			(_value, index) => {
				started.push(index);
				return index === 0 ? firstMapper.promise : secondMapper.promise;
			},
			{ concurrency: 2, abortController },
		);
		void resultPromise.then(
			() => {
				settled = true;
			},
			() => {
				settled = true;
			},
		);

		firstMapper.reject(mapperError);
		await flushMicrotasks();

		expect(abortController.signal.aborted).toBe(true);
		expect(abortController.signal.reason).toBe(mapperError);
		expect(started).toEqual([0, 1]);
		expect(settled).toBe(false);

		secondMapper.resolve("finished after failure");
		await expect(resultPromise).rejects.toBe(mapperError);
		expect(settled).toBe(true);
	});

	it("logs secondary mapper errors but not rejections caused by the shared abort", async () => {
		const abortController = new AbortController();
		const firstMapper = deferred<string>();
		const secondMapper = deferred<string>();
		const abortingMapper = deferred<string>();
		const firstError = new Error("first failure");
		const secondError = new Error("independent secondary failure");
		const consoleError = vi.spyOn(console, "error").mockImplementation(() => undefined);

		const resultPromise = mapAsync(
			["first", "second", "aborting"],
			(_value, index) => {
				if (index === 0) {
					return firstMapper.promise;
				}
				if (index === 1) {
					return secondMapper.promise;
				}
				return abortingMapper.promise;
			},
			{ concurrency: 3, abortController },
		);

		firstMapper.reject(firstError);
		await flushMicrotasks();
		secondMapper.reject(secondError);
		abortingMapper.reject(abortController.signal.reason);

		await expect(resultPromise).rejects.toBe(firstError);
		expect(consoleError).toHaveBeenCalledExactlyOnceWith(
			"mapAsync mapper at index 1 rejected after another failure or abort",
			secondError,
		);
	});

	it("rejects a pre-aborted invocation without starting work", async () => {
		const abortController = new AbortController();
		const abortReason = new Error("already aborted");
		const mapper = vi.fn();
		abortController.abort(abortReason);

		await expect(mapAsync(["value"], mapper, { concurrency: 1, abortController })).rejects.toBe(
			abortReason,
		);
		expect(mapper).not.toHaveBeenCalled();
	});

	it("stops starting work after an external abort and drains active mappers", async () => {
		const abortController = new AbortController();
		const firstMapper = deferred<string>();
		const secondMapper = deferred<string>();
		const abortReason = new Error("cancelled");
		const started: number[] = [];
		let settled = false;

		const resultPromise = mapAsync(
			["first", "second", "never started"],
			(_value, index) => {
				started.push(index);
				return index === 0 ? firstMapper.promise : secondMapper.promise;
			},
			{ concurrency: 2, abortController },
		);
		void resultPromise.then(
			() => {
				settled = true;
			},
			() => {
				settled = true;
			},
		);

		abortController.abort(abortReason);
		await flushMicrotasks();

		expect(started).toEqual([0, 1]);
		expect(settled).toBe(false);

		firstMapper.resolve("first completed");
		secondMapper.resolve("second completed");
		await expect(resultPromise).rejects.toBe(abortReason);
		expect(settled).toBe(true);
	});
});
